// src/pages/notifications/NotificationPage.jsx
import React, { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useNotifications } from '../../hooks/UseNotifications';

function NotificationPage() {
  const navigate = useNavigate();

  const {
    notifications,
    total,
    loading,
    error,
    page,
    setPage,
    size,
    setSize,
    keyword,
    setKeyword,
    level,
    setLevel,
    from,
    setFrom,
    to,
    setTo,
    refresh,
  } = useNotifications({ page: 1, size: 20, sort: 'collectedAt,desc' });

  const totalPages = useMemo(() => {
    return Math.max(1, Math.ceil((total || 0) / (size || 1)));
  }, [total, size]);

  const handleOpen = (item) => {
    navigate(`/notifications/${item.id}`, { state: { notification: item } });
  };

  return (
    <div className="page-container">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
        <h1>알림(=AI 결과)</h1>
        <button className="btn" onClick={() => navigate('/notifications/stats')}>
          통계 보기
        </button>
      </div>

      <div className="filter-bar" style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 12 }}>
        <input
          type="text"
          placeholder="키워드(경로/이벤트/설명)"
          value={keyword}
          onChange={(e) => { setKeyword(e.target.value); setPage(1); }}
          style={{ minWidth: 260 }}
        />

        <select
          value={level}
          onChange={(e) => { setLevel(e.target.value); setPage(1); }}
        >
          <option value="ALL">전체</option>
          <option value="DANGER">DANGER</option>
          <option value="WARNING">WARNING</option>
          <option value="SAFE">SAFE</option>
        </select>

        <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          from
          <input
            type="date"
            value={from}
            onChange={(e) => { setFrom(e.target.value); setPage(1); }}
          />
        </label>

        <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          to
          <input
            type="date"
            value={to}
            onChange={(e) => { setTo(e.target.value); setPage(1); }}
          />
        </label>

        <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          size
          <select value={size} onChange={(e) => { setSize(Number(e.target.value)); setPage(1); }}>
            <option value={10}>10</option>
            <option value={20}>20</option>
            <option value={50}>50</option>
            <option value={100}>100</option>
          </select>
        </label>

        <button className="btn" onClick={refresh}>
          새로고침
        </button>
      </div>

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>에러: {String(error.message || error)}</p>}

      {!loading && !error && (
        <>
          <p style={{ opacity: 0.8, marginBottom: 8 }}>
            총 {total}건 / {page} / {totalPages}
          </p>

          {notifications.length === 0 ? (
            <p>알림이 없습니다.</p>
          ) : (
            <ul className="notification-list">
              {notifications.map((item) => (
                <li
                  key={item.id}
                  className="notification-item"
                  onClick={() => handleOpen(item)}
                  style={{ cursor: 'pointer', padding: 12, borderBottom: '1px solid #eee' }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
                      <span className={`badge badge-${(item.aiLabel || 'UNKNOWN').toLowerCase()}`}>
                        {item.aiLabel || 'UNKNOWN'}
                      </span>
                      <strong style={{ wordBreak: 'break-all' }}>{item.path}</strong>
                    </div>
                    <div style={{ whiteSpace: 'nowrap', opacity: 0.8 }}>
                      {item.collectedAt}
                    </div>
                  </div>

                  <div style={{ marginTop: 6, opacity: 0.9 }}>
                    <span style={{ marginRight: 10 }}>
                      <strong>event:</strong> {item.eventType}
                    </span>
                    {item.aiDetail && (
                      <span style={{ color: '#444' }}>
                        {item.aiDetail.length > 120 ? item.aiDetail.slice(0, 120) + '…' : item.aiDetail}
                      </span>
                    )}
                  </div>
                </li>
              ))}
            </ul>
          )}

          <div style={{ display: 'flex', gap: 8, marginTop: 12, alignItems: 'center' }}>
            <button className="btn" disabled={page <= 1} onClick={() => setPage((p) => Math.max(1, p - 1))}>
              이전
            </button>
            <span>
              {page} / {totalPages}
            </span>
            <button className="btn" disabled={page >= totalPages} onClick={() => setPage((p) => Math.min(totalPages, p + 1))}>
              다음
            </button>
          </div>
        </>
      )}
    </div>
  );
}

export default NotificationPage;
